    def _move(self):
        if not self.outgoing:
            while self.incoming:
                self.outgoing.append(self.incoming.pop())
    def pop(self):
        self._move()
        return self.outgoing.pop()
    def peek(self):
        self._move()
        return self.outgoing[-1]
    def empty(self):
        return not self.incoming and not self.outgoing

