class Solution:
    def canPartition(self, nums: List[int]) -> bool:
        total = sum(nums)
        if total % 2:
            return False
        target = total // 2
        reachable = [False] * (target + 1)
        reachable[0] = True
        for x in nums:
            for value in range(target, x - 1, -1):
                reachable[value] = reachable[value] or reachable[value - x]
        return reachable[target]

