class Solution:
    def numIslands(self, grid: List[List[str]]) -> int:
        m, n = len(grid), len(grid[0])
        seen = set()
        answer = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] != '1' or (i, j) in seen:
                    continue
                answer += 1
                stack = [(i, j)]
                seen.add((i, j))
                while stack:
                    x, y = stack.pop()
                    for nx, ny in [(x-1,y),(x+1,y),(x,y-1),(x,y+1)]:
                        if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == '1' and (nx,ny) not in seen:
                            seen.add((nx,ny))
                            stack.append((nx,ny))
        return answer

